"""Curated case assembly. Monetary stages deliberately remain separate."""
import json,re
from pathlib import Path
ROOT=Path(__file__).resolve().parent
OUT=ROOT.parent/'corporate.json'
D={'snapshot':'2026-10-07','sources':[],'entities':[],'relationships':[],'records':[],'localities':[]}
ROUTE='/follow-the-money'
manifest=json.loads((ROOT/'manifest.json').read_text())
receipts={r['sourceId']:r for r in manifest['receipts']}
def source(id,title,publisher,date,locator,summary,tier='documented',limitations=[]):
 r=receipts[id]
 D['sources'].append(dict(id=id,title=title,url=r['url'],publisher=publisher,publishedAt=date,retrievedAt='2026-10-07',locator=locator,summary=summary,tier=tier,limitations=limitations+[f"Retained original/extract SHA-256 receipt: research/raw/deep-investigation/corporate-evidence/manifest.json ({id})."]))
def geo(ids,states=[],note='National company, sale or policy context; no state-level spending allocation inferred.',basis='national-context'):
 return [dict(scope='multi-state' if len(states)>1 else 'state' if states else 'national',stateCodes=states,localityIds=[],basis=basis,note=note,sourceIds=ids)]
def dim(ids,domains,layers,states=[],note=None):
 return dict(sourceIds=ids,domains=domains,layers=layers,geography=geo(ids,states,note or ('Documented asset/project location; neither headquarters nor inferred expenditure.' if states else 'National company, sale or policy context; no state-level spending allocation inferred.'),'project-location' if states else 'national-context'),route=ROUTE,limitations=[])
def entity(id,label,type,ids,domains,identity,summary,family='capital',states=[],canonical=None):
 r=dict(id=id,label=label,type=type,family=family,resolved=True,identityBasis=identity,summary=summary,**dim(ids,domains,['legal'] if family=='enforce' else ['organisations'],states));
 if canonical:r['canonicalId']=canonical
 D['entities'].append(r)
def amount(v,stage,period,unit='crore',currency='INR'):return dict(value=v,currency=currency,unit=unit,stage=stage,period=period)
def edge(id,a,b,label,summary,ids,domains,layers,kind='contracted',tier='documented',status='documented',date=None,end=None,asof=None,amounts=[],states=[],limits=[],alternatives=[],falsifier=None,responses=[],records=[]):
 D['relationships'].append(dict(id=id,**{'from':a,'to':b},kind=kind,label=label,tier=tier,status=status,statusAsOf=asof or date,fromDate=date,toDate=end,dateBasis='Exact event or financial-position date from the cited record.' if date else 'Historical period is stated in the summary; an exact day is not inferred.',summary=summary,alternativeExplanations=alternatives,falsifier=falsifier,responseIds=responses,recordIds=records,amounts=amounts,**{**dim(ids,domains,layers,states),'limitations':limits}))
def record(id,title,summary,ids,entities,edges,domains,layers,date,asof,period,response,alternatives,falsifier,amounts=[],states=[],kind='investigation-case',tier='documented',status='source-bounded',end=None,limits=[]):
 D['records'].append(dict(id=id,title=title,summary=summary,kind=kind,tier=tier,status=status,statusAsOf=asof,fromDate=date,toDate=end,dateBasis='Dates delimit documented events; statusAsOf is the latest supporting source date, not a claim of continuous current legal status.',entityIds=entities,relationshipIds=edges,period=period,response=response,alternativeExplanations=alternatives,falsifier=falsifier,amounts=amounts,**{**dim(ids,domains,layers,states),'limitations':limits}))

